		// "logg in" is in no table. Collapse the double and try once more.
		if n := len(stem); n >= 2 && stem[n-1] == stem[n-2] {
			if joined, ok := searchCompoundPhrases[stem[:n-1]+" "+tail]; ok {
				return joined, true
			}
		}
	}
