			}
		}
		t.Logf("%-22s token-matched=%v  substring-matched=%v", n, tokHits, subHits)
	}
}

func lower(s string) string {
	out := []rune{}
	for _, r := range s {
		if r >= 'A' && r <= 'Z' {
			r += 32
		}
		out = append(out, r)
	}
	return string(out)
}

func nameContainsSub(lowerName, term string) bool {
	if len(term) < 3 {
		return false
	}
	if contains(lowerName, term) {
		return true
	}
	if hasSuffix(term, "es") && len(term) > 4 && contains(lowerName, term[:len(term)-2]) {
		return true
	}
	if hasSuffix(term, "s") && len(term) > 3 && contains(lowerName, term[:len(term)-1]) {
		return true
	}
	return false
}

func contains(s, sub string) bool  { return len(sub) <= len(s) && index(s, sub) >= 0 }
func hasSuffix(s, x string) bool   { return len(s) >= len(x) && s[len(s)-len(x):] == x }
func index(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
GOEOF
