    print("%-8s %-9s %8.4f %8.4f" % (f,"MRR",stats["main"][2],stats["pruned"][2]))
print("\ndiffering (instance,form) pairs, gold rank:")
def rank(top,gold):
    for i,p in enumerate(top or [],1):
        if p in gold: return i
    return None
for r in rows:
    g=set(r["gold"])
    for f in ("title","first2"):
        a=(r["arms"]["main"].get(f) or {}); b=(r["arms"]["pruned"].get(f) or {})
        if not a: continue
        ra,rb=rank(a.get("top"),g),rank(b.get("top"),g)
        if ra!=rb: print("  %-38s %-7s main=%s pruned=%s" % (r["iid"],f,ra,rb))
PYEOF
